const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;

pub const __cit = "[web:144]";

fn xorshift64star(state: *u64) u64 {
    var x = state.*;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    state.* = x;
    return x * 0x2545F4914F6CDD1D;
}

fn prngFloatSigned(state: *u64, scale: f32) f32 {
    const r = xorshift64star(state);
    const u = @as(f32, @floatFromInt(@as(u32, @truncate(r)))) / @as(f32, 4294967295.0);
    return (u * 2.0 - 1.0) * scale;
}

pub const TunnelDiodeActivation = struct {
    peak_voltage: f32,
    valley_voltage: f32,
    peak_current: f32,
    valley_current: f32,

    pub fn init(peak_v: f32, valley_v: f32, peak_i: f32, valley_i: f32) TunnelDiodeActivation {
        return .{
            .peak_voltage = peak_v,
            .valley_voltage = valley_v,
            .peak_current = peak_i,
            .valley_current = valley_i,
        };
    }

    pub fn forward(self: TunnelDiodeActivation, x: f32) f32 {
        const pv = if (self.peak_voltage != 0.0) self.peak_voltage else 1e-6;
        const normalized = x / pv;
        if (normalized <= 0.0) return 0.0;
        if (normalized < 1.0) {
            const s = 1.0 / (1.0 + math.exp(-10.0 * (normalized - 0.5)));
            return (self.peak_current * normalized) * s;
        }
        const a = self.peak_current;
        return a * (1.0 - math.exp(-normalized));
    }

    pub fn backward(self: TunnelDiodeActivation, x: f32, grad_output: f32) f32 {
        const h: f32 = 1e-4;
        const f_plus = self.forward(x + h);
        const f_minus = self.forward(x - h);
        const derivative = (f_plus - f_minus) / (2.0 * h);
        return grad_output * derivative;
    }
};

pub const KolmogorovArnoldNetwork = struct {
    allocator: Allocator,
    input_dim: usize,
    output_dim: usize,
    grid_size: usize,
    order: usize,
    bounds: f32,

    knots: []f32,
    coeffs: []f32,
    bias: []f32,

    const MaxOrder: usize = 8;

    pub fn init(
        allocator: Allocator,
        input_dim: usize,
        output_dim: usize,
        grid_size: usize,
        order: usize,
        bounds: f32,
        seed: u64,
    ) !KolmogorovArnoldNetwork {
        if (input_dim == 0 or output_dim == 0 or grid_size < 2 or order < 2) return error.InvalidDimensions;
        if (order > MaxOrder) return error.OrderTooLarge;

        const degree = order - 1;
        const knots_len = grid_size + order;

        var knots = try allocator.alloc(f32, knots_len);
        errdefer allocator.free(knots);

        const left = -bounds;
        const right = bounds;
        const interior_count = grid_size - degree;

        for (0..order) |i| {
            knots[i] = left;
        }

        if (interior_count > 1) {
            const denom = @as(f32, @floatFromInt(interior_count - 1));
            for (0..interior_count) |k| {
                const t = @as(f32, @floatFromInt(k)) / denom;
                knots[degree + k] = left + (right - left) * t;
            }
        } else {
            knots[degree] = left;
        }

        for (0..order) |i| {
            knots[grid_size + i] = right;
        }

        const coeffs_len = output_dim * input_dim * grid_size;
        var coeffs = try allocator.alloc(f32, coeffs_len);
        errdefer allocator.free(coeffs);

        var bias = try allocator.alloc(f32, output_dim);
        errdefer allocator.free(bias);

        var st: u64 = seed ^ 0x9E3779B97F4A7C15;
        for (0..coeffs_len) |idx| {
            coeffs[idx] = prngFloatSigned(&st, 0.02);
        }
        for (0..output_dim) |o| {
            bias[o] = prngFloatSigned(&st, 0.02);
        }

        return .{
            .allocator = allocator,
            .input_dim = input_dim,
            .output_dim = output_dim,
            .grid_size = grid_size,
            .order = order,
            .bounds = bounds,
            .knots = knots,
            .coeffs = coeffs,
            .bias = bias,
        };
    }

    fn clampToDomain(self: *const KolmogorovArnoldNetwork, x: f32) f32 {
        const left = self.knots[self.order - 1];
        const right = self.knots[self.grid_size];
        if (x < left) return left;
        if (x > right) return right;
        return x;
    }

    fn findSpan(self: *const KolmogorovArnoldNetwork, x_in: f32) usize {
        const n = self.grid_size - 1;
        const p = self.order - 1;
        var x = self.clampToDomain(x_in);

        const right = self.knots[n + 1];
        if (x >= right) return n;

        var low: usize = p;
        var high: usize = n + 1;
        var mid: usize = (low + high) / 2;

        while (!(x >= self.knots[mid] and x < self.knots[mid + 1])) {
            if (x < self.knots[mid]) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high) / 2;
        }
        return mid;
    }

    fn basisAll(self: *const KolmogorovArnoldNetwork, x_in: f32, out_basis: []f32) void {
        mem.set(f32, out_basis, 0.0);

        const p = self.order - 1;
        const x = self.clampToDomain(x_in);
        const span = self.findSpan(x);

        var N_buf: [MaxOrder]f32 = undefined;
        var left_buf: [MaxOrder]f32 = undefined;
        var right_buf: [MaxOrder]f32 = undefined;

        var N = N_buf[0..self.order];
        var left = left_buf[0..self.order];
        var right = right_buf[0..self.order];

        N[0] = 1.0;

        var j: usize = 1;
        while (j <= p) : (j += 1) {
            left[j] = x - self.knots[span + 1 - j];
            right[j] = self.knots[span + j] - x;

            var saved: f32 = 0.0;
            var r: usize = 0;
            while (r < j) : (r += 1) {
                const denom = right[r + 1] + left[j - r];
                const temp = if (denom != 0.0) (N[r] / denom) else 0.0;
                N[r] = saved + right[r + 1] * temp;
                saved = left[j - r] * temp;
            }
            N[j] = saved;
        }

        const first = span - p;
        var k: usize = 0;
        while (k <= p) : (k += 1) {
            const idx = first + k;
            if (idx < out_basis.len) out_basis[idx] = N[k];
        }
    }

    inline fn coeffIndex(self: *const KolmogorovArnoldNetwork, o: usize, i: usize, j: usize) usize {
        return (o * self.input_dim + i) * self.grid_size + j;
    }

    pub fn forward(self: *const KolmogorovArnoldNetwork, input: []const f32, output: []f32) !void {
        if (input.len != self.input_dim) return error.InvalidInput;
        if (output.len != self.output_dim) return error.InvalidOutput;

        mem.set(f32, output, 0.0);

        var basis_buf = try self.allocator.alloc(f32, self.grid_size);
        defer self.allocator.free(basis_buf);

        for (0..self.output_dim) |o| {
            var acc: f32 = self.bias[o];
            for (0..self.input_dim) |i| {
                self.basisAll(input[i], basis_buf);
                for (0..self.grid_size) |j| {
                    const b = basis_buf[j];
                    if (b != 0.0) {
                        acc += self.coeffs[self.coeffIndex(o, i, j)] * b;
                    }
                }
            }
            output[o] = acc;
        }
    }

    pub fn deinit(self: *KolmogorovArnoldNetwork) void {
        self.allocator.free(self.knots);
        self.allocator.free(self.coeffs);
        self.allocator.free(self.bias);
        self.* = undefined;
    }
};

pub const ImplicitNeuralRepresentation = struct {
    allocator: Allocator,
    coordinate_dim: usize,
    output_dim: usize,
    hidden_dims: []usize,
    fourier_scale: f32,
    num_fourier_features: usize,

    layers: []KolmogorovArnoldNetwork,
    fourier_weights: []f32,

    pub fn init(
        allocator: Allocator,
        coordinate_dim: usize,
        output_dim: usize,
        hidden_dims_in: []const usize,
        fourier_scale: f32,
        num_fourier_features: usize,
        seed: u64,
    ) !ImplicitNeuralRepresentation {
        if (coordinate_dim == 0 or output_dim == 0) return error.InvalidDimensions;
        if (num_fourier_features == 0) return error.InvalidDimensions;

        var hidden_dims = try allocator.alloc(usize, hidden_dims_in.len);
        errdefer allocator.free(hidden_dims);
        mem.copyForwards(usize, hidden_dims, hidden_dims_in);

        const encoded_dim = coordinate_dim + 2 * num_fourier_features;

        const layer_count = hidden_dims.len + 1;
        var layers = try allocator.alloc(KolmogorovArnoldNetwork, layer_count);
        errdefer {
            for (layers[0..layer_count]) |*l| {
                if (@intFromPtr(l.knots.ptr) != 0) l.deinit();
            }
            allocator.free(layers);
        }

        var prev_dim = encoded_dim;
        var st: u64 = seed ^ 0xD6E8FEB86659FD93;

        for (0..hidden_dims.len) |idx| {
            const h = hidden_dims[idx];
            layers[idx] = try KolmogorovArnoldNetwork.init(
                allocator,
                prev_dim,
                h,
                64,
                4,
                5.0,
                xorshift64star(&st),
            );
            prev_dim = h;
        }

        layers[layer_count - 1] = try KolmogorovArnoldNetwork.init(
            allocator,
            prev_dim,
            output_dim,
            64,
            4,
            5.0,
            xorshift64star(&st),
        );

        var fourier_weights = try allocator.alloc(f32, num_fourier_features * coordinate_dim);
        errdefer allocator.free(fourier_weights);

        var st2: u64 = seed ^ 0xA5A3564E27F4A09D;
        for (0..fourier_weights.len) |k| {
            fourier_weights[k] = prngFloatSigned(&st2, fourier_scale);
        }

        return .{
            .allocator = allocator,
            .coordinate_dim = coordinate_dim,
            .output_dim = output_dim,
            .hidden_dims = hidden_dims,
            .fourier_scale = fourier_scale,
            .num_fourier_features = num_fourier_features,
            .layers = layers,
            .fourier_weights = fourier_weights,
        };
    }

    fn encode(self: *const ImplicitNeuralRepresentation, coords: []const f32, out_encoded: []f32) !void {
        if (coords.len != self.coordinate_dim) return error.InvalidInput;
        const expected = self.coordinate_dim + 2 * self.num_fourier_features;
        if (out_encoded.len != expected) return error.InvalidOutput;

        mem.copyForwards(f32, out_encoded[0..self.coordinate_dim], coords);

        const two_pi: f32 = 2.0 * math.pi;

        for (0..self.num_fourier_features) |k| {
            var dot: f32 = 0.0;
            const row_off = k * self.coordinate_dim;
            for (0..self.coordinate_dim) |j| {
                dot += self.fourier_weights[row_off + j] * coords[j];
            }
            out_encoded[self.coordinate_dim + k] = math.cos(two_pi * dot);
            out_encoded[self.coordinate_dim + self.num_fourier_features + k] = math.sin(two_pi * dot);
        }
    }

    fn maxLayerWidth(self: *const ImplicitNeuralRepresentation) usize {
        var m: usize = self.output_dim;
        for (self.hidden_dims) |h| {
            if (h > m) m = h;
        }
        const encoded = self.coordinate_dim + 2 * self.num_fourier_features;
        if (encoded > m) m = encoded;
        return m;
    }

    pub fn forward(self: *const ImplicitNeuralRepresentation, coords: []const f32, output: []f32) !void {
        if (output.len != self.output_dim) return error.InvalidOutput;

        const encoded_dim = self.coordinate_dim + 2 * self.num_fourier_features;
        const maxw = self.maxLayerWidth();

        var buf_a = try self.allocator.alloc(f32, maxw);
        defer self.allocator.free(buf_a);
        var buf_b = try self.allocator.alloc(f32, maxw);
        defer self.allocator.free(buf_b);

        const in0 = buf_a[0..encoded_dim];
        try self.encode(coords, in0);

        var cur_in: []f32 = in0;
        var cur_in_len: usize = encoded_dim;

        for (0..self.layers.len) |li| {
            const out_len = if (li < self.hidden_dims.len) self.hidden_dims[li] else self.output_dim;
            const cur_out = buf_b[0..out_len];

            try self.layers[li].forward(cur_in[0..cur_in_len], cur_out);

            cur_in = buf_b[0..out_len];
            cur_in_len = out_len;

            const tmp = buf_a;
            buf_a = buf_b;
            buf_b = tmp;
        }

        mem.copyForwards(f32, output, cur_in[0..self.output_dim]);
    }

    pub fn deinit(self: *ImplicitNeuralRepresentation) void {
        for (self.layers) |*l| {
            l.deinit();
        }
        self.allocator.free(self.layers);
        self.allocator.free(self.fourier_weights);
        self.allocator.free(self.hidden_dims);
        self.* = undefined;
    }
};

pub const MechanisticInterpretabilityEngine = struct {
    allocator: Allocator,
    neuron_importance: []f32,
    connection_causality: []f32,
    num_neurons: usize,

    learned_circuits: std.StringHashMap([]usize),

    pub fn init(allocator: Allocator, num_neurons: usize) !MechanisticInterpretabilityEngine {
        if (num_neurons == 0) return error.InvalidDimensions;

        var neuron_importance = try allocator.alloc(f32, num_neurons);
        errdefer allocator.free(neuron_importance);
        mem.set(f32, neuron_importance, 0.0);

        var connection_causality = try allocator.alloc(f32, num_neurons * num_neurons);
        errdefer allocator.free(connection_causality);
        mem.set(f32, connection_causality, 0.0);

        return .{
            .allocator = allocator,
            .neuron_importance = neuron_importance,
            .connection_causality = connection_causality,
            .num_neurons = num_neurons,
            .learned_circuits = std.StringHashMap([]usize).init(allocator),
        };
    }

    pub fn computeImportance(self: *MechanisticInterpretabilityEngine, activations: []const f32, gradients: []const f32) !void {
        if (activations.len != self.num_neurons or gradients.len != self.num_neurons) return error.InvalidInput;
        for (0..self.num_neurons) |i| {
            self.neuron_importance[i] = math.fabs(activations[i] * gradients[i]);
        }
    }

    pub fn identifyCircuit(self: *MechanisticInterpretabilityEngine, threshold: f32) !std.ArrayList(usize) {
        var important = std.ArrayList(usize).init(self.allocator);
        for (0..self.num_neurons) |i| {
            if (self.neuron_importance[i] > threshold) try important.append(i);
        }
        return important;
    }

    pub fn deinit(self: *MechanisticInterpretabilityEngine) void {
        var it = self.learned_circuits.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.learned_circuits.deinit();

        self.allocator.free(self.neuron_importance);
        self.allocator.free(self.connection_causality);
        self.* = undefined;
    }
};

pub const CausalKnowledgeGraph = struct {
    allocator: Allocator,
    entities: std.StringHashMap(usize),
    relations: std.ArrayList(CausalRelation),
    mechanism_rules: std.ArrayList(MechanismRule),

    pub const CausalRelation = struct {
        source_id: usize,
        target_id: usize,
        causal_strength: f32,
        uncertainty: f32,
    };

    pub const MechanismRule = struct {
        condition: std.ArrayList(usize),
        consequence: std.ArrayList(usize),
        confidence: f32,
        discovery_timestamp_ms: i64,
    };

    pub fn init(allocator: Allocator) CausalKnowledgeGraph {
        return .{
            .allocator = allocator,
            .entities = std.StringHashMap(usize).init(allocator),
            .relations = std.ArrayList(CausalRelation).init(allocator),
            .mechanism_rules = std.ArrayList(MechanismRule).init(allocator),
        };
    }

    pub fn addEntity(self: *CausalKnowledgeGraph, name: []const u8) !usize {
        if (self.entities.get(name)) |id| return id;
        const id: usize = self.entities.count();
        const key_copy = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(key_copy);
        try self.entities.put(key_copy, id);
        return id;
    }

    pub fn addCausalRelation(self: *CausalKnowledgeGraph, source_id: usize, target_id: usize, strength: f32, uncertainty: f32) !void {
        try self.relations.append(.{
            .source_id = source_id,
            .target_id = target_id,
            .causal_strength = strength,
            .uncertainty = uncertainty,
        });
    }

    pub fn addMechanismRule(self: *CausalKnowledgeGraph, condition: []const usize, consequence: []const usize, confidence: f32) !void {
        var cond = std.ArrayList(usize).init(self.allocator);
        errdefer cond.deinit();
        try cond.appendSlice(condition);

        var cons = std.ArrayList(usize).init(self.allocator);
        errdefer cons.deinit();
        try cons.appendSlice(consequence);

        try self.mechanism_rules.append(.{
            .condition = cond,
            .consequence = cons,
            .confidence = confidence,
            .discovery_timestamp_ms = std.time.milliTimestamp(),
        });
    }

    pub fn inferCausalEffect(self: *const CausalKnowledgeGraph, source_id: usize, target_id: usize) f32 {
        var total: f32 = 0.0;
        var count: usize = 0;
        for (self.relations.items) |rel| {
            if (rel.source_id == source_id and rel.target_id == target_id) {
                const u = math.clamp(rel.uncertainty, 0.0, 1.0);
                total += rel.causal_strength * (1.0 - u);
                count += 1;
            }
        }
        if (count == 0) return 0.0;
        return total / @as(f32, @floatFromInt(count));
    }

    pub fn deinit(self: *CausalKnowledgeGraph) void {
        var it = self.entities.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.entities.deinit();

        self.relations.deinit();

        for (self.mechanism_rules.items) |*rule| {
            rule.condition.deinit();
            rule.consequence.deinit();
        }
        self.mechanism_rules.deinit();

        self.* = undefined;
    }
};

