    };

    pub const RLExperience = struct {
        state: []f32,
        action: []u8,
        reward: f32,
        next_state: []f32,
        terminal: bool,
    };

    pub fn init(allocator: Allocator) System2Reasoner {
        return .{
            .allocator = allocator,
            .external_memory = std.ArrayList(MemoryEntry).init(allocator),
            .reasoning_trace = std.ArrayList(ReasoningStep).init(allocator),
            .belief_state = std.StringHashMap(f32).init(allocator),
            .goal_stack = std.ArrayList(Goal).init(allocator),
            .reinforcement_buffer = std.ArrayList(RLExperience).init(allocator),
        };
    }

    fn updateOrInsertMemory(self: *System2Reasoner, key: []const u8, value: []const u8, confidence: f32) !void {
        for (self.external_memory.items) |*entry| {
            if (mem.eql(u8, entry.key, key)) {
                self.allocator.free(entry.value);
                entry.value = try self.allocator.dupe(u8, value);
                entry.confidence = confidence;
                entry.last_updated_ms = std.time.milliTimestamp();
                return;
            }
        }
        try self.external_memory.append(.{
            .key = try self.allocator.dupe(u8, key),
            .value = try self.allocator.dupe(u8, value),
            .confidence = confidence,
            .access_count = 0,
            .last_updated_ms = std.time.milliTimestamp(),
        });
    }

    pub fn storeMemory(self: *System2Reasoner, key: []const u8, value: []const u8, confidence: f32) !void {
        try self.updateOrInsertMemory(key, value, confidence);
    }

    pub fn retrieveMemory(self: *System2Reasoner, key: []const u8) ?[]const u8 {
        for (self.external_memory.items) |*entry| {
            if (mem.eql(u8, entry.key, key)) {
                entry.access_count += 1;
                return entry.value;
            }
        }
        return null;
    }

    pub fn recordReasoningStep(self: *System2Reasoner, action: []const u8, reasoning: []const u8, confidence: f32) !u32 {
        var derived = std.ArrayList([]u8).init(self.allocator);

        const id: u32 = @intCast(self.reasoning_trace.items.len);
        try self.reasoning_trace.append(.{
            .step_id = id,
            .action = try self.allocator.dupe(u8, action),
            .reasoning = try self.allocator.dupe(u8, reasoning),
            .confidence = confidence,
            .timestamp_ms = std.time.milliTimestamp(),
            .derived_knowledge = derived,
        });
        return id;
    }

    pub fn addDerivedKnowledge(self: *System2Reasoner, step_id: u32, knowledge: []const u8) !void {
        if (step_id >= self.reasoning_trace.items.len) return error.InvalidStep;
        try self.reasoning_trace.items[step_id].derived_knowledge.append(try self.allocator.dupe(u8, knowledge));
    }

    pub fn pushGoal(self: *System2Reasoner, goal_name: []const u8, priority: f32) !void {
        var subgoals = std.ArrayList([]u8).init(self.allocator);
        try self.goal_stack.append(.{
            .name = try self.allocator.dupe(u8, goal_name),
            .priority = priority,
            .decomposed_subgoals = subgoals,
            .status = .pending,
        });
    }

    pub fn decomposeGoal(self: *System2Reasoner, goal_idx: usize, subgoals: []const []const u8) !void {
        if (goal_idx >= self.goal_stack.items.len) return error.InvalidGoal;
        for (subgoals) |sg| {
            try self.goal_stack.items[goal_idx].decomposed_subgoals.append(try self.allocator.dupe(u8, sg));
        }
    }

    pub fn updateBeliefState(self: *System2Reasoner, key: []const u8, value: f32) !void {
        const key_copy = try self.allocator.dupe(u8, key);
        var gop = try self.belief_state.getOrPut(key_copy);
        if (gop.found_existing) {
            self.allocator.free(key_copy);
            gop.value_ptr.* = value;
        } else {
            gop.value_ptr.* = value;
        }
    }

    pub fn queryBelief(self: *System2Reasoner, key: []const u8) ?f32 {
        return self.belief_state.get(key);
    }

    pub fn recordRLExperience(self: *System2Reasoner, state: []const f32, action: []const u8, reward: f32, next_state: []const f32, terminal: bool) !void {
        try self.reinforcement_buffer.append(.{
            .state = try self.allocator.dupe(f32, state),
            .action = try self.allocator.dupe(u8, action),
            .reward = reward,
            .next_state = try self.allocator.dupe(f32, next_state),
            .terminal = terminal,
        });
    }

    pub fn planMultiStep(self: *System2Reasoner, goal_description: []const u8, horizon: usize) !std.ArrayList([]u8) {
        var plan = std.ArrayList([]u8).init(self.allocator);
        try self.pushGoal(goal_description, 1.0);

        for (0..horizon) |step| {
            const s = try std.fmt.allocPrint(self.allocator, "step_{d}", .{step});
            try plan.append(s);
        }
        return plan;
    }

    pub fn freePlan(self: *System2Reasoner, plan: *std.ArrayList([]u8)) void {
        for (plan.items) |p| self.allocator.free(p);
        plan.deinit();
    }

    pub fn learnFromExperience(self: *System2Reasoner) f32 {
        if (self.reinforcement_buffer.items.len == 0) return 0.0;
        var total: f32 = 0.0;
        for (self.reinforcement_buffer.items) |exp| total += exp.reward;
        return total / @as(f32, @floatFromInt(self.reinforcement_buffer.items.len));
    }

    pub fn deinit(self: *System2Reasoner) void {
        for (self.external_memory.items) |entry| {
            self.allocator.free(entry.key);
            self.allocator.free(entry.value);
        }
        self.external_memory.deinit();

        for (self.reasoning_trace.items) |step| {
            self.allocator.free(step.action);
            self.allocator.free(step.reasoning);
            for (step.derived_knowledge.items) |k| self.allocator.free(k);
            step.derived_knowledge.deinit();
        }
        self.reasoning_trace.deinit();

        var it = self.belief_state.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.belief_state.deinit();

        for (self.goal_stack.items) |goal| {
            self.allocator.free(goal.name);
            for (goal.decomposed_subgoals.items) |sg| self.allocator.free(sg);
            goal.decomposed_subgoals.deinit();
        }
        self.goal_stack.deinit();

        for (self.reinforcement_buffer.items) |exp| {
            self.allocator.free(exp.state);
            self.allocator.free(exp.action);
            self.allocator.free(exp.next_state);
        }
        self.reinforcement_buffer.deinit();

        self.* = undefined;
    }
};

pub const CausalInferenceEngine = struct {
    allocator: Allocator,
    intervention_history: std.ArrayList(Intervention),
    observational_data: std.ArrayList(Observation),

    pub const Intervention = struct {
        variable: []u8,
        value: f32,
        timestamp_ms: i64,
        effect_size: f32,
    };

    pub const Observation = struct {
        variables: std.StringHashMap(f32),
        timestamp_ms: i64,
    };

    pub fn init(allocator: Allocator) CausalInferenceEngine {
        return .{
            .allocator = allocator,
            .intervention_history = std.ArrayList(Intervention).init(allocator),
            .observational_data = std.ArrayList(Observation).init(allocator),
        };
    }

    pub fn addObservation(self: *CausalInferenceEngine, vars: *const std.StringHashMap(f32)) !void {
        var obs_vars = std.StringHashMap(f32).init(self.allocator);
        errdefer {
            var it = obs_vars.iterator();
            while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
            obs_vars.deinit();
        }

        var iter = vars.iterator();
        while (iter.next()) |entry| {
            const k = try self.allocator.dupe(u8, entry.key_ptr.*);
            errdefer self.allocator.free(k);
            try obs_vars.put(k, entry.value_ptr.*);
        }

        try self.observational_data.append(.{
            .variables = obs_vars,
            .timestamp_ms = std.time.milliTimestamp(),
        });
    }

    pub fn recordIntervention(self: *CausalInferenceEngine, variable: []const u8, value: f32) !void {
        try self.intervention_history.append(.{
            .variable = try self.allocator.dupe(u8, variable),
            .value = value,
            .timestamp_ms = std.time.milliTimestamp(),
            .effect_size = 0.0,
        });
    }

    pub fn identifyTreatmentEffect(self: *CausalInferenceEngine, treatment_var: []const u8, outcome_var: []const u8) f32 {
        if (self.observational_data.items.len < 2) return 0.0;

        var treated_sum: f32 = 0.0;
        var treated_n: usize = 0;
        var control_sum: f32 = 0.0;
        var control_n: usize = 0;

        for (self.observational_data.items) |obs| {
            const t = obs.variables.get(treatment_var) orelse continue;
            const o = obs.variables.get(outcome_var) orelse continue;
            if (t > 0.5) {
                treated_sum += o;
                treated_n += 1;
            } else {
                control_sum += o;
                control_n += 1;
            }
        }

        if (treated_n == 0 or control_n == 0) return 0.0;

        const treated_mean = treated_sum / @as(f32, @floatFromInt(treated_n));
        const control_mean = control_sum / @as(f32, @floatFromInt(control_n));
        return treated_mean - control_mean;
    }

    pub fn estimateCounterfactual(self: *CausalInferenceEngine, observed_state: *const std.StringHashMap(f32), outcome_var: []const u8) f32 {
        if (self.observational_data.items.len == 0) return 0.0;

        var weighted_sum: f32 = 0.0;
        var weight_total: f32 = 0.0;

        for (self.observational_data.items) |obs| {
            var similarity: f32 = 1.0;

            var it = observed_state.iterator();
            while (it.next()) |entry| {
                const obs_val_opt = obs.variables.get(entry.key_ptr.*);
                if (obs_val_opt) |obs_val| {
                    const diff = math.fabs(obs_val - entry.value_ptr.*);
                    similarity *= 1.0 / (1.0 + diff);
                } else {
                    similarity *= 0.5;
                }
            }

            if (similarity < 0.05) continue;

            const out = obs.variables.get(outcome_var) orelse continue;
            weighted_sum += out * similarity;
            weight_total += similarity;
        }

        if (weight_total == 0.0) return 0.0;
        return weighted_sum / weight_total;
    }

    pub fn deinit(self: *CausalInferenceEngine) void {
        for (self.intervention_history.items) |intv| self.allocator.free(intv.variable);
        self.intervention_history.deinit();

        for (self.observational_data.items) |obs| {
            var it = obs.variables.iterator();
            while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
            obs.variables.deinit();
        }
        self.observational_data.deinit();

        self.* = undefined;
    }
};

pub const ContinualLearningManager = struct {
    allocator: Allocator,
    learned_tasks: std.ArrayList(TaskMemory),
    consolidation_buffer: std.ArrayList(ExperienceBuffer),
    plasticity_rate: f32,
    consolidation_strength: f32,

    pub const TaskMemory = struct {
        task_id: usize,
        feature_representations: [][]f32,
        task_specific_weights: []f32,
        performance_on_task: f32,
    };

    pub const ExperienceBuffer = struct {
        timestamp_ms: i64,
        experience_vector: []f32,
        importance_weight: f32,
    };

    pub fn init(allocator: Allocator, plasticity: f32) ContinualLearningManager {
        return .{
            .allocator = allocator,
            .learned_tasks = std.ArrayList(TaskMemory).init(allocator),
            .consolidation_buffer = std.ArrayList(ExperienceBuffer).init(allocator),
            .plasticity_rate = plasticity,
            .consolidation_strength = 0.9,
        };
    }

    pub fn learnNewTask(self: *ContinualLearningManager, task_id: usize, features: []const []const f32, performance: f32) !void {
        if (features.len == 0) return error.InvalidInput;

        const features_copy = try self.allocator.alloc([]f32, features.len);
        errdefer self.allocator.free(features_copy);

        for (features, 0..) |feat, i| {
            features_copy[i] = try self.allocator.dupe(f32, feat);
        }
        errdefer {
            for (features_copy) |f| self.allocator.free(f);
        }

        const weights = try self.allocator.alloc(f32, features.len);
        errdefer self.allocator.free(weights);

        const w = 1.0 / @as(f32, @floatFromInt(features.len));
        for (0..features.len) |i| weights[i] = w;

        try self.learned_tasks.append(.{
            .task_id = task_id,
            .feature_representations = features_copy,
            .task_specific_weights = weights,
            .performance_on_task = performance,
        });
    }

    pub fn consolidateExperience(self: *ContinualLearningManager, experience: []const f32, importance_weight: f32) !void {
        try self.consolidation_buffer.append(.{
            .timestamp_ms = std.time.milliTimestamp(),
            .experience_vector = try self.allocator.dupe(f32, experience),
            .importance_weight = importance_weight,
        });
    }

    pub fn transferLearning(self: *ContinualLearningManager, source_task_id: usize, target_task_features: []const []const f32) f32 {
        if (self.learned_tasks.items.len == 0) return 0.0;

        var best: f32 = 0.0;

        for (self.learned_tasks.items) |task| {
            if (task.task_id != source_task_id) continue;

            var sim: f32 = 0.0;
            const n = @min(task.feature_representations.len, target_task_features.len);

            for (0..n) |i| {
                const src = task.feature_representations[i];
                const tgt = target_task_features[i];

                const m = @min(src.len, tgt.len);
                if (m == 0) continue;

                var overlap: f32 = 0.0;
                for (0..m) |j| {
                    const diff = math.fabs(src[j] - tgt[j]);
                    overlap += 1.0 / (1.0 + diff);
                }
                overlap /= @as(f32, @floatFromInt(m));
                sim += overlap * task.task_specific_weights[i];
            }

            if (sim > best) best = sim;
        }

        return best * self.consolidation_strength;
    }

    pub fn preventCatastrophicForgetting(self: *ContinualLearningManager, new_task_features: []const f32, old_task_prototypes: []const []const f32) f32 {
        var retention: f32 = 1.0;

        for (old_task_prototypes) |proto| {
            if (proto.len != new_task_features.len or proto.len == 0) continue;

            var similarity: f32 = 0.0;
            for (0..proto.len) |i| {
                const diff = math.fabs(proto[i] - new_task_features[i]);
                similarity += 1.0 / (1.0 + diff);
            }
            similarity /= @as(f32, @floatFromInt(proto.len));
            retention *= 1.0 - self.plasticity_rate * (1.0 - similarity);
        }

        return 1.0 - retention;
    }

    pub fn deinit(self: *ContinualLearningManager) void {
        for (self.learned_tasks.items) |task| {
            for (task.feature_representations) |f| self.allocator.free(f);
            self.allocator.free(task.feature_representations);
            self.allocator.free(task.task_specific_weights);
        }
        self.learned_tasks.deinit();

        for (self.consolidation_buffer.items) |exp| self.allocator.free(exp.experience_vector);
        self.consolidation_buffer.deinit();

        self.* = undefined;
    }
};

